const text = $input.first().json.message.text || '';
const chatId = $input.first().json.message.chat.id;

// Extraire la notion après /apprendre
const notion = text.replace('/apprendre', '').trim();

return [{ json: { notion: notion || 'investissement', chatId } }];

const text = $input.first().json.message.text || '';
const chatId = $input.first().json.message.chat.id;
const ticker = text.replace('/analyse', '').trim().toUpperCase();
return [{ json: { ticker: ticker || '', chatId } }];

